<span class="line"><span style="color:#383A42;">        console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(xhr.</span><span style="color:#E45649;">status</span><span style="color:#0184BC;"> +</span><span style="color:#50A14F;"> &#39;:&#39;</span><span style="color:#0184BC;"> +</span><span style="color:#383A42;"> xhr.</span><span style="color:#E45649;">statusText</span><span style="color:#383A42;">);</span></span>
